func tCodeOk(emonT *testing.T, code int32) int32 {
	// A script code is four letters, the first uppercase and the others lowercase, and the enum spells it.
	var t *strings.Builder = port.NewText()
	port.AssertEq(emonT, ocrport.ScEmitName(t, code), 1, "an ISO 15924 code of `sc`")
	port.AssertThat(emonT, (code/16777216) >= 65, "the first letter is from A")
	port.AssertThat(emonT, (code/16777216) <= 90, "to Z")
	port.AssertThat(emonT, ((code/65536)%256) >= 97, "the second is lowercase")
	port.AssertThat(emonT, ((code/256)%256) >= 97, "and the third")
	port.AssertThat(emonT, (code%256) >= 97, "and the fourth")
	return 0
}

func tPushp(c *port.Cells, p int32) int32 {
	// Push the non-zero bytes of the packed cell `p` as code points: a name of up to four chars.
	var d int32 = 16777216
	var b int32 = 0
	for d > 0 {
		b = (p / d) % 256
		if b != 0 {
			port.CellsPush(c, b)
		}
		d = d / 256
	}
	return 0
}

func tPack(a int32, b int32, d int32, e int32) int32 {
	var c *port.Cells = port.NewCells()
	port.CellsPush(c, a)
	port.CellsPush(c, b)
	port.CellsPush(c, d)
	if e != 0 {
		port.CellsPush(c, e)
	}
	return ocrport.OpPackCells(c)
}

